function ENTAILS(Gamma, A):
    ids <- sorted atoms occurring in Gamma ∪ {A}
    for each combo in LP^|ids|:
        v <- assignment of ids from combo
        if for all B in Gamma: DESIG(EVAL(v, B)):    # v is a model
            if not DESIG(EVAL(v, A)):                 # v refutes A
                return False
    return True

DESIG(x) := (x != ff)

